#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-31
#
# probe-payload-rules.sh (#3849): does EVERY rule ork ships in
# src/skills/setup/references/operator-permissions.json actually deny, or do we
# only believe it does?
#
# probe-permission-deny.sh (#3835) proves the MECHANISM with one synthetic rule.
# That is not the same claim. The divergence purge deleted 16 blocking hooks and
# handed their job to this payload, so the payload IS the protection now, and an
# untested rule in it is a hole with a comment on it.
#
# Per rule: a CONTROL arm with no deny rule, which must execute (a probe that
# cannot watch the thing happen measures nothing), and a TRIP arm carrying that
# ONE rule, which must not. Single-rule trip arms on purpose: the shipped
# payload is their union, so per-rule proof implies payload proof, while a
# whole-payload arm would let one rule mask another (Read of a dotenv file would
# block the read step of the Edit case and look like a pass).
#
# Observation is by EFFECT, never by denial text. STUB_GREP scans the whole
# request including the injected CLAUDE.md, and this machine's CLAUDE.md
# contains the word "permission", so a denial-text grep reports a hit in an arm
# that was never denied. Measured 2026-08-31; it is why each case plants a
# random canary instead.
#
# 31 of the 42 rules are executed for real. The other 11 are marked not-live in
# payload-trip-cases.json because running the trip case IS the harm the rule
# exists to prevent, and they are reported as NOT PROVEN, never as passes.
#
# Exit: 0 every live rule denied and every control executed
#       1 REGRESSED: a shipped rule did not deny (named in the output)
#       2 could-not-observe (claude missing, a control arm that never ran, or
#         payload/case-map drift)
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../../.." && pwd)"
PAYLOAD="${PROBE_PAYLOAD:-$ROOT/src/skills/setup/references/operator-permissions.json}"
# PROBE_CASES lets a spelling experiment reuse this exact arm path.
CASES="${PROBE_CASES:-$HERE/payload-trip-cases.json}"
CLAUDE_BIN="${CLAUDE_BIN:-claude}"
ONLY="${PROBE_ONLY:-}"
ARM_TIMEOUT="${PROBE_TIMEOUT:-45}"

command -v "$CLAUDE_BIN" >/dev/null || { echo "COULD-NOT-OBSERVE: $CLAUDE_BIN not on PATH"; exit 2; }
command -v node >/dev/null || { echo "COULD-NOT-OBSERVE: node not on PATH"; exit 2; }
[ -f "$PAYLOAD" ] || { echo "COULD-NOT-OBSERVE: payload missing at $PAYLOAD"; exit 2; }
[ -f "$CASES" ]   || { echo "COULD-NOT-OBSERVE: case map missing at $CASES"; exit 2; }

SCRATCH="$(mktemp -d "${TMPDIR:-/tmp}/payload-rules.XXXXXX")"
cleanup() { [ "${SMOKE_KEEP:-0}" = "1" ] || rm -rf "$SCRATCH"; }
trap cleanup EXIT

# ---------------------------------------------------------------- coverage ---
# Both directions. A rule with no case is the failure this file exists to
# prevent: it would be added, shipped, and never tested, which is exactly how
# the plugin's OWN settings.json carried 26 dead rules since v7.0.0.
if ! python3 "$HERE/payload-coverage.py" "$PAYLOAD" "$CASES" > "$SCRATCH/coverage.txt" 2>&1; then
  cat "$SCRATCH/coverage.txt"; exit 2
fi
cat "$SCRATCH/coverage.txt"

python3 "$HERE/payload-cases-tsv.py" "$CASES" > "$SCRATCH/cases.tsv" || {
  echo "COULD-NOT-OBSERVE: could not read the case map"; exit 2; }

# -------------------------------------------------------------------- arms ---
STUB_PID=""
start_stub() {
  STUB_LOG="$SCRATCH/req-$1.jsonl" STUB_PORT_FILE="$SCRATCH/port-$1" \
    STUB_TOOL_USE_SEQ="$2" STUB_GREP="$3" \
    node "$HERE/stub-anthropic-api.mjs" > "$SCRATCH/stub-$1.log" 2>&1 &
  STUB_PID=$!
  local i
  for i in $(seq 1 60); do [ -s "$SCRATCH/port-$1" ] && return 0; sleep 0.1; done
  return 1
}

setup_git_repo() {
  git init -q -b "$2" "$1"
  git init -q --bare "$1.origin"
  ( cd "$1" \
    && git -c user.email=p@p -c user.name=p commit -q --allow-empty -m seed \
    && git remote add origin "$1.origin" ) >/dev/null 2>&1
}
git_pushed() { git -C "$1.origin" rev-parse --verify "refs/heads/$2" >/dev/null 2>&1; }

run_arm() {
  local arm=$1 settings=$2 wd=$3 fh=$4 seq=$5 pat=$6 turns=$7 port rc watchdog stub_pid
  start_stub "$arm" "$seq" "$pat" || { echo "stub-failed"; return 2; }
  port="$(cat "$SCRATCH/port-$arm")"
  # Capture the pid in a LOCAL first. `( sleep N; kill -9 "$STUB_PID" )` expands
  # STUB_PID when the kill finally runs, which is after the sleep, by which time
  # the variable names a LATER arm's stub. Measured 2026-08-31: a stale watchdog
  # shot the live stub out from under a running arm, and claude then sat
  # retrying a dead endpoint, so the sweep crawled at ~5 minutes per case.
  local stub_pid=$STUB_PID
  # >/dev/null on the watchdog is load-bearing, not tidiness. The subshell
  # inherits this script's stdout, so when the script is run through a pipe its
  # lingering `sleep` keeps the write end open and the READER blocks for the
  # full timeout after the probe has already finished. Measured 2026-08-31:
  # every case cost exactly ARM_TIMEOUT seconds, which read as "claude is slow"
  # when claude itself answers in under a second.
  ( sleep "$ARM_TIMEOUT"; kill -9 "$stub_pid" 2>/dev/null ) >/dev/null 2>&1 & watchdog=$!
  ( cd "$wd" && env -u CLAUDECODE -u CLAUDE_CODE_OAUTH_TOKEN -u CLAUDE_CONFIG_DIR \
      HOME="$fh" ANTHROPIC_BASE_URL="http://127.0.0.1:$port" ANTHROPIC_API_KEY="payload-probe" \
      DISABLE_TELEMETRY=1 DISABLE_ERROR_REPORTING=1 \
      "$CLAUDE_BIN" -p "do it" --settings "$settings" --dangerously-skip-permissions \
        --output-format json --max-turns "$turns" ) \
    > "$SCRATCH/out-$arm.json" 2> "$SCRATCH/err-$arm.txt" < /dev/null
  rc=$?
  # Kill the sleep too: killing the subshell leaves its child holding the fd.
  pkill -P "$watchdog" >/dev/null 2>&1
  kill "$watchdog" 2>/dev/null; kill "$STUB_PID" 2>/dev/null; STUB_PID=""
  return $rc
}

# A control arm carries empty settings. If CC records a permission denial there
# anyway, CC refuses that command on its own, under --dangerously-skip-permissions,
# with no rule involved. That is not "unobservable": it is the strongest possible
# result for a rule, namely that we did not need it. Measured on `rm -rf ~`.
cc_denied_natively() {
  node -e '
const fs=require("fs");
try{const d=JSON.parse(fs.readFileSync(process.argv[1],"utf8"));
  process.exit((d.permission_denials||[]).length>0?0:1);}catch{process.exit(1);}' "$SCRATCH/out-$1.json"
}

canary_reached_model() {
  node -e '
const fs=require("fs");let hit=false;
try{for(const l of fs.readFileSync(process.argv[1],"utf8").trim().split("\n")){
  const r=JSON.parse(l); if(r.grep_hit) hit=true; }}catch{}
process.exit(hit?0:1);' "$SCRATCH/req-$1.jsonl"
}

PASS=0; TWIN=0; NATIVE=0; REGRESSED=0; UNOBSERVED=0; NOTPROVEN=0
declare -a REG_LIST=() UNOBS_LIST=() NOTPROVEN_LIST=() TWIN_LIST=() NATIVE_LIST=()

n=0
# US (0x1f), not tab: tab is IFS whitespace, so bash collapses a run of
# tabs and an empty column vanishes, shifting every later field left. That
# defect reported two rules as REGRESSED that do in fact deny (2026-08-31).
while IFS=$'\x1f' read -r rule mode kind target command setup_sh effect_sh reason twin; do
  [ -n "$rule" ] || continue
  if [ -n "$ONLY" ] && [[ "$rule" != *"$ONLY"* ]]; then continue; fi

  if [ "$mode" = "not-live" ]; then
    NOTPROVEN=$((NOTPROVEN + 1)); NOTPROVEN_LIST+=("$rule :: $reason"); continue
  fi

  n=$((n + 1))
  CANARY="PROBE-$(od -An -tx1 -N6 /dev/urandom | tr -d ' \n')"
  CANARY2="EDITED-$CANARY"
  echo "[$n] $rule"

  arm_result=""; control_ran=1; trip_ran=1
  for arm in control trip; do
    WORKDIR="$SCRATCH/$arm-$n"; FAKE_HOME="$SCRATCH/$arm-$n-home"
    mkdir -p "$WORKDIR" "$FAKE_HOME"
    SETTINGS="$SCRATCH/settings-$arm-$n.json"
    if [ "$arm" = "control" ]; then
      printf '{}\n' > "$SETTINGS"
    else
      # mode=twin denies the TWIN, because the rule itself is measurably inert
      # and the twin is what actually blocks this tool call.
      deny_rule="$rule"; [ "$mode" = "twin" ] && deny_rule="$twin"
      python3 -c 'import json,sys;json.dump({"permissions":{"deny":[sys.argv[1]]}},open(sys.argv[2],"w"))' "$deny_rule" "$SETTINGS"
    fi

    t="$(eval "printf %s \"$target\"" 2>/dev/null)"
    turns=2; pat="$CANARY"
    case "$kind" in
      read)
        mkdir -p "$(dirname "$t")"; printf '%s\n' "$CANARY" > "$t"
        seq="$(python3 -c 'import json,sys;print(json.dumps([{"name":"Read","input":{"file_path":sys.argv[1]}}]))' "$t")" ;;
      write)
        mkdir -p "$(dirname "$t")"; rm -f "$t"
        seq="$(python3 -c 'import json,sys;print(json.dumps([{"name":"Write","input":{"file_path":sys.argv[1],"content":sys.argv[2]}}]))' "$t" "$CANARY")" ;;
      edit)
        mkdir -p "$(dirname "$t")"; printf '%s\n' "$CANARY" > "$t"; turns=3
        seq="$(python3 -c 'import json,sys;p,o,nw=sys.argv[1:4];print(json.dumps([{"name":"Read","input":{"file_path":p}},{"name":"Edit","input":{"file_path":p,"old_string":o,"new_string":nw}}]))' "$t" "$CANARY" "$CANARY2")" ;;
      bash)
        case "$setup_sh" in
          "SETUP_GIT_REPO "*) setup_git_repo "$WORKDIR" "${setup_sh##* }" ;;
          *) eval "$setup_sh" >/dev/null 2>&1 ;;
        esac
        pat="__absent_marker__"
        seq="$(python3 -c 'import json,sys;print(json.dumps([{"name":"Bash","input":{"command":sys.argv[1]}}]))' "$command")" ;;
    esac

    run_arm "$arm-$n" "$SETTINGS" "$WORKDIR" "$FAKE_HOME" "$seq" "$pat" "$turns"

    executed=1
    case "$kind" in
      read)  canary_reached_model "$arm-$n" && executed=0 ;;
      write) [ -e "$t" ] && grep -qF "$CANARY" "$t" 2>/dev/null && executed=0 ;;
      edit)  [ -e "$t" ] && grep -qF "$CANARY2" "$t" 2>/dev/null && executed=0 ;;
      bash)
        case "$effect_sh" in
          "GIT_PUSHED "*) git_pushed "$WORKDIR" "${effect_sh##* }" && executed=0 ;;
          *) eval "$effect_sh" >/dev/null 2>&1 && executed=0 ;;
        esac ;;
    esac
    if [ $executed -eq 0 ]; then arm_result="$arm_result $arm=RAN"; else arm_result="$arm_result $arm=blocked"; fi
    if [ "$arm" = "control" ]; then control_ran=$executed; else trip_ran=$executed; fi
  done

  if [ "$control_ran" -ne 0 ] && cc_denied_natively "control-$n"; then
    echo "     CC REFUSES IT NATIVELY:$arm_result (control had NO deny rule and CC denied anyway)"
    NATIVE=$((NATIVE + 1)); NATIVE_LIST+=("$rule")
  elif [ "$control_ran" -ne 0 ]; then
    echo "     COULD-NOT-OBSERVE:$arm_result (control never executed; this case is unmeasurable here)"
    UNOBSERVED=$((UNOBSERVED + 1)); UNOBS_LIST+=("$rule")
  elif [ "$trip_ran" -eq 0 ]; then
    echo "     REGRESSED:$arm_result (the shipped rule did NOT deny)"
    REGRESSED=$((REGRESSED + 1)); REG_LIST+=("$rule")
  elif [ "$mode" = "twin" ]; then
    echo "     PASS via twin $twin:$arm_result"
    TWIN=$((TWIN + 1)); TWIN_LIST+=("$rule covered by $twin")
  else
    echo "     PASS:$arm_result"
    PASS=$((PASS + 1))
  fi
done < "$SCRATCH/cases.tsv"

echo
echo "=============================================================="
echo "  payload rules: $PASS proven, $TWIN via twin, $NATIVE refused by CC itself, $REGRESSED regressed, $UNOBSERVED unobservable, $NOTPROVEN not-live"
echo "=============================================================="
if [ ${#REG_LIST[@]} -gt 0 ]; then
  echo "REGRESSED rules (the payload does not enforce these):"; printf '  %s\n' "${REG_LIST[@]}"
fi
if [ ${#UNOBS_LIST[@]} -gt 0 ]; then
  echo "COULD NOT OBSERVE:"; printf '  %s\n' "${UNOBS_LIST[@]}"
fi
if [ ${#NATIVE_LIST[@]} -gt 0 ]; then
  echo "REDUNDANT: CC refuses these with no rule at all, so the payload rule is belt-and-braces:"
  printf '  %s\n' "${NATIVE_LIST[@]}"
fi
if [ ${#TWIN_LIST[@]} -gt 0 ]; then
  echo "INERT AS SPELLED, protection delivered by the named twin:"; printf '  %s\n' "${TWIN_LIST[@]}"
fi
if [ ${#NOTPROVEN_LIST[@]} -gt 0 ]; then
  echo "NOT PROVEN, by design (running the trip case is the harm itself):"; printf '  %s\n' "${NOTPROVEN_LIST[@]}"
fi
[ "$REGRESSED" -gt 0 ] && exit 1
[ "$UNOBSERVED" -gt 0 ] && exit 2
exit 0
